SCRIPT=src[src.index('<img class="logo"'):]
SC=[0,2.6,6.6,12.2,17.2,20.2,25]
def B(t,at,a='pop',fs=None): return f'<div class="big"{f" style=%sfont-size:{fs}px;letter-spacing:-3px%s"%(chr(34),chr(34)) if fs else ""} data-in="{at}" data-a="{a}">{t}</div>'
def H(t,at,r=False,a='left'): return f'<div class="hl{" r" if r else ""}" data-in="{at}" data-a="{a}">{t}</div>'
def N(t,at): return f'<div class="note" data-in="{at}" data-a="up">{t}</div>'
def cell(c):
    if isinstance(c,dict):
        cls=c.get('cls','');return f'<div class="c {cls}" data-c="{c["st"]},{c.get("du",1.4)}" data-f="{c["f"]}" data-t="{c["t"]}" data-dp="{c.get("dp",0)}" data-suf="{c.get("suf","")}">{c["f"]:.{c.get("dp",0)}f}{c.get("suf","")}</div>'
    if isinstance(c,tuple): return f'<div class="c {c[1]}">{c[0]}</div>'
    return f'<div class="c">{c}</div>'
def CARD(at,rows,hd=None,fs=76,gap=0.3):
    h=''
    if hd: h='<div class="hd"><span style="flex:0 0 140px"></span>'+''.join(f'<span>{x}</span>' for x in hd)+'</div>'
    r=''.join(f'<div class="row" style="font-size:{fs}px" data-in="{round(at+0.3+gap*i,2)}" data-a="left"><div class="p">{l}</div>{"".join(cell(c) for c in cs)}</div>' for i,(l,cs) in enumerate(rows))
    return f'<div class="card" data-in="{at}" data-a="up">{h}{r}</div>'
def VS(at,items,fs=128):
    return '<div class="vs">'+''.join(f'<div data-in="{round(at+0.5*i,2)}" data-a="pop"><div class="lb">{lb}</div><div class="n {c}" style="font-size:{fs}px">{n}</div></div>' for i,(lb,n,c) in enumerate(items))+'</div>'
def M(at,pre,val,post):
    v=f'<b data-c="{val["st"]},{val.get("du",1.2)}" data-f="{val["f"]}" data-t="{val["t"]}" data-dp="{val.get("dp",0)}" data-suf="{val.get("suf","")}">{val["f"]}</b>' if isinstance(val,dict) else f'<b>{val}</b>'
    return f'<div class="meter" data-in="{at}" data-a="up">{pre}{v}{post}</div>'
def PTS(items): return H('오늘의 핵심 📌',0.1)+''.join(f'<div class="pt" data-in="{0.4+0.4*i}" data-a="left"><i>{i+1}</i>{x}</div>' for i,x in enumerate(items))
def QUIZ(q,opts,fs=96,qfs=88):
    return (H('QUIZ',0.05,True,'pop')+B(q,0.3,'up',qfs)+f'<div class="ans" data-in="0.8" data-a="pop">'+''.join(f'<div style="font-size:{fs}px">{o}</div>' for o in opts)+'</div>'
     +'<div class="cd" id="cd" data-in="1.3" data-a="pop">3</div>'+N('정답은 <b>설명란</b>에서!',1.3))
def build(n,scenes,label=None):
    N_=f'{n:02d}';o=CSS+f'<div class="top">{label or "홀덤 꿀팁 #"+N_}</div>\n<div class="prog"><i id="pb"></i></div>\n'
    for i,sc in enumerate(scenes):
        g=' style="gap:30px"' if i==4 else ''
        o+=f'<div class="sc" data-s="{SC[i]}" data-e="{SC[i+1]}"{g}>\n'+'\n'.join(sc)+'\n</div>\n'
    open(f'motion/tip{N_}.html','w').write(o+SCRIPT)
